```javascript
// Importation de la bibliothèque Discord.js v14
const { Client, GatewayIntentBits, Events } = require('discord.js');

// Création d'un nouveau client Discord
const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

// Connexion du client au Discord
client.on(Events.ClientReady, () => {
  console.log('Bot prêt !');
});

// Commande "bannir"
client.on(Events.InteractionCreate, async interaction => {
  if (!interaction.isChatInputCommand() || interaction.commandName !== 'bannir') return;

  // Vérification des permissions
  if (!interaction.member.permissions.has('BAN_MEMBERS')) {
    await interaction.reply({
      content: 'Vous n'avez pas la permission de bannir les utilisateurs !',
      ephemeral: true,
    });
    return;
  }

  // Vérification du membre cible
  const member = interaction.guild.members.cache.get(interaction.options.getUser('utilisateur').id);
  if (!member) {
    await interaction.reply({
      content: 'Utilisateur introuvable !',
      ephemeral: true,
    });
    return;
  }

  // Bannissement du membre
  try {
    await interaction.guild.ban(member, { reason: `Banni par ${interaction.user.tag}` });
    await interaction.reply({ content: `${member.user.tag} a été banni !` });
  } catch (error) {
    console.error(error);
    await interaction.reply({ content: 'Une erreur est survenue, veuillez réessayer plus tard.' });
  }
});

// Connexion du client au Discord
client.login(process.env.TOKEN);
