Voici une fonction C++ qui prend une référence à un std::string contenant du texte au format Markdown et renvoie un std::string contenant du texte au format HTML, en utilisant la bibliothèque Pugl (PUG for C++) :

```cpp
#include <iostream>
#include <string>
#include <pugixml.hpp>

// Fonction pour convertir du Markdown en HTML
std::string convertMarkdownToHTML(const std::string& markdown) {
    // Création d'un document XML en mémoire
    pugi::xml_document doc;
    if (doc.load_string(markdown.c_str()) == pugi::parse_error) {
        // Gestion d'erreurs de parsing
        std::cerr << "Erreur de parsing du Markdown : " << markdown << std::endl;
        return "";
    }

    // Création d'un nouveau document HTML
    pugi::xml_document html_doc;
    pugi::xml_node root = html_doc.append_child(pugi::node_element);
    root.append_attribute("xmlns") = "http://www.w3.org/1999/xhtml";
    root.set_name("html");

    // Ajout du head
    pugi::xml_node head = root.append_child(pugi::node_element);
    head.set_name("head");
    pugi::xml_node title = head.append_child(pugi::node_element);
    title.set_name("title");
    title.append_child(pugi::node_pcdata).set_value("Markdown to HTML", "");

    // Ajout du body
    pugi::xml_node body = root.append_child(pugi::node_element);
    body.set_name("body");

    // Parcours des noeuds Markdown et conversion en HTML
    for (pugi::xml_node node = doc.root().first_child(); node; node = node.next_sibling()) {
        if (node.type() == pugi::node_element) {
            pugi::xml_node converted_node = body.append_copy(node);
            // Conversion des balises Markdown en HTML
            if (node.name() == "h1") {
                converted_node.set_name("h1");
            } else if (node.name() == "h2") {
                converted_node.set_name("h2");
            } else if (node.name() == "h3") {
                converted_node.set_name("h3");
            } else if (node.name() == "h4") {
                converted_node.set_name("h4");
            } else if (node.name() == "h5") {
                converted_node.set_name("h5");
            } else if (node.name() == "h6") {
                converted_node.set_name("h6");
            } else if (node.name() == "p") {
                converted_node.set_name("p");
            } else if (node.name() == "ul") {
                converted_node.set_name("ul");
            } else if (node.name() == "ol") {
                converted_node.set_name("ol");
            } else if (node.name() == "li") {
                converted_node.set_name("li");
            } else if (node.name() == "strong") {
                converted_node.set_name("strong");
            } else if (node.name() == "em") {
                converted_node.set_name("em");
            } else if (node.name() == "a") {
                pugi::xml_node href = node.child("href");
                converted_node.append_attribute("href") = href.value();
                converted_node.remove_child(href);
            }
        }
    }

    // Conversion du document XML en chaîne de caractères
    std::stringstream html_stream;
    html_doc.save(html_stream);

    // Retourne le texte HTML
    return html_stream.str();
}

int main() {
    std::string markdown = "## Titre H2\n\nUne *phrase* en **bold** et _italique_!\n\n- Un\n- Deux\n- Trois\n\n[lien](https://example.com)";
    std::string html = convertMarkdownToHTML(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

Cette fonction utilise la bibliothèque Pugl pour convertir le document Markdown en un document XML, puis parcourt les noeuds XML pour convertir les balises Markdown en HTML. Notez que cette fonction ne traite pas toutes les balises Markdown, mais seulement les plus courantes (h1 à h6, p, ul, ol, li, strong, em, a). De plus, cette fonction ne traite pas les balises Markdown avancées (tableaux, images, etc.). Il est recommandé de compléter cette fonction en fonction de vos besoins.

