Voici un code de base en C pour le jeu du serpent qui utilise la bibliothèque SDL :

```c
#include <stdio.h>
#include <stdlib.h>
#include <SDL2/SDL.h>

// Définitions des constantes
#define WINDOW_WIDTH 800
#define WINDOW_HEIGHT 600
#define SNAKE_WIDTH 20
#define SNAKE_HEIGHT 20
#define FRUIT_WIDTH 20
#define FRUIT_HEIGHT 20
#define GRID_WIDTH 40
#define GRID_HEIGHT 30

// Définitions des structures
typedef struct {
    int x, y;
} Point;

typedef struct {
    Point head, tail;
    int length;
    int dx, dy;
} Snake;

// Fonctions de dessin
SDL_Surface *load_image(const char *filename);
void draw_grid(SDL_Renderer *renderer);
void draw_snake(SDL_Renderer *renderer, Snake *snake);
void draw_fruit(SDL_Renderer *renderer, Point fruit);

// Fonctions de gestion
void move_snake(Snake *snake);
void eat_fruit(Snake *snake, Point *fruit);
void check_collisions(Snake *snake, Point *fruit);

// Fonctions principales
int main(int argc, char *argv[]) {
    // Initialisation SDL
    SDL_Init(SDL_INIT_VIDEO);
    SDL_Window *window = SDL_CreateWindow(
        "Snake",
        SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
        WINDOW_WIDTH, WINDOW_HEIGHT,
        SDL_WINDOW_SHOWN
    );
    SDL_Renderer *renderer = SDL_CreateRenderer(
        window, -1, SDL_RENDERER_ACCELERATED
    );

    // Initialisation du serpent
    Snake snake = {
        .head = { 10, 10 },
        .tail = { 8, 10 },
        .length = 2,
        .dx = 1,
        .dy = 0
    };

    // Initialisation du fruit
    Point fruit = { 20, 20 };

    // Boucle de jeu
    bool running = true;
    SDL_Event event;
    while (running) {
        // Gestion des événements
        while (SDL_PollEvent(&event)) {
            switch (event.type) {
                case SDL_QUIT:
                    running = false;
                    break;
                case SDL_KEYDOWN:
                    switch (event.key.keysym.sym) {
                        case SDLK_LEFT:
                            if (snake.dx != 1) {
                                snake.dx = -1;
                                snake.dy = 0;
                            }
                            break;
                        case SDLK_RIGHT:
                            if (snake.dx != -1) {
                                snake.dx = 1;
                                snake.dy = 0;
                            }
                            break;
                        case SDLK_UP:
                            if (snake.dy != 1) {
                                snake.dx = 0;
                                snake.dy = -1;
                            }
                            break;
                        case SDLK_DOWN:
                            if (snake.dy != -1) {
                                snake.dx = 0;
                                snake.dy = 1;
                            }
                            break;
                        default:
                            break;
                    }
                    break;
                default:
                    break;
            }
        }

        // Actualisation de l'interface
        SDL_SetRenderDrawColor(renderer, 0, 0, 0, SDL_ALPHA_OPAQUE);
        SDL_RenderClear(renderer);
        draw_grid(renderer);
        draw_snake(renderer, &snake);
        draw_fruit(renderer, &fruit);
        SDL_RenderPresent(renderer);

        // Gestion des collisions
        check_collisions(&snake, &fruit);

        // Mouvement du serpent
        move_snake(&snake);
        eat_fruit(&snake, &fruit);
    }

    // Nettoyage SDL
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();

    return 0;
}

// Fonctions de dessin
SDL_Surface *load_image(const char *filename) {
    SDL_Surface *image = SDL_LoadBMP(filename);
    if (image == NULL) {
        printf("Impossible d'ouvrir l'image %s : %s\n", filename, SDL_GetError());
        exit(1);
    }
    return image;
}

void draw_grid(SDL_Renderer *renderer) {
    SDL_Surface *grid_image = load_image("grid.bmp");
    int grid_width = WINDOW_WIDTH / GRID_WIDTH;
    int grid_height = WINDOW_HEIGHT / GRID_HEIGHT;
    for (int I = 0; I < GRID_WIDTH; i++) {
        for (int j = 0; j < GRID_HEIGHT; j++) {
            SDL_Rect dst = {
                I * grid_width, j * grid_height,
                grid_width, grid_height
            };
            SDL_BlitSurface(grid_image, NULL, renderer, &dst);
        }
    }
    SDL_FreeSurface(grid_image);
}

void draw_snake(SDL_Renderer *renderer, Snake *snake) {
    SDL_Surface *snake_image = load_image("snake.bmp");
    SDL_Rect snake_rect = {
        snake->head.x * SNAKE_WIDTH, snake->head.y * SNAKE_HEIGHT,
        SNAKE_WIDTH, SNAKE_HEIGHT
    };
    SDL_BlitSurface(snake_image, NULL, renderer, &snake_rect);
    for (int I = snake->length - 2; I >= 0; i--) {
        snake_rect.x = snake->tail.x * SNAKE_WIDTH;
        snake_rect.y = snake->tail.y * SNAKE_HEIGHT;
        snake_rect.w = SNAKE_WIDTH;
        snake_rect.h = SNAKE_HEIGHT;
        SDL_Rect dst_rect = {
            (snake->tail.x - 1) * SNAKE_WIDTH, snake->tail.y * SNAKE_HEIGHT,
            SNAKE_WIDTH, SNAKE_HEIGHT
        };
        SDL_BlitSurface(snake_image, &dst_rect, renderer, &snake_rect);
        snake->tail.x = snake->head.x;
        snake->tail.y = snake->head.y;
    }
    SDL_FreeSurface(snake_image);
}

void draw_fruit(SDL_Renderer *renderer, Point fruit) {
    SDL_Surface *fruit_image = load_image("fruit.bmp");
    SDL_Rect fruit_rect = {
        fruit.x * FRUIT_WIDTH, fruit.y * FRUIT_HEIGHT,
        FRUIT_WIDTH, FRUIT_HEIGHT
    };
    SDL_BlitSurface(fruit_image, NULL, renderer, &fruit_rect);
    SDL_FreeSurface(fruit_image);
}

// Fonctions de gestion
void move_snake(Snake *snake) {
    snake->head.x += snake->dx;
    snake->head.y += snake->dy;
    if (snake->head.x < 0 || snake->head.x >= GRID_WIDTH ||
        snake->head.y < 0 || snake->head.y >= GRID_HEIGHT) {
        // Collision avec un mur
        snake->head.x -= snake->dx;
        snake->head.y -= snake->dy;
    }
}

void eat_fruit(Snake *snake, Point *fruit) {
    if (snake->head.x == fruit->x && snake->head.y == fruit->y) {
        snake->length++;
        fruit->x = (rand() % GRID_WIDTH) * SNAKE_WIDTH;
        fruit->y = (rand() % GRID_HEIGHT) * SNAKE_HEIGHT;
    }
}

void check_collisions(Snake *snake, Point *fruit) {
    // Collision avec un mur
    if (snake->head.x < 0 || snake->head.x >= GRID_WIDTH ||
        snake->head.y < 0 || snake->head.y >= GRID_HEIGHT) {
        printf("Game over!\n");
        exit(0);
    }

    // Collision avec le fruit
    if (snake->head.x == fruit->x && snake->head.y == fruit->y) {
        eat_fruit(snake, fruit);
    }

    // Collision avec la queue du serpent
    for (int I = snake->length - 2; I >= 0; i--) {
        if (snake->head.x == snake->tail.x && snake->head.y == snake->tail.y) {
            printf("Game over!\n");
            exit(0);
        }
        snake->tail.x = snake->tail.next_x;
        snake->tail.y = snake->tail.next_y;
    }
}
```

