function isPrimeValid(n) {
  if (n < 2) {
    return false;
  }
  for (let I = 2; I <= Math.sqrt(n); i++) {
    if (n % I === 0) {
      return false;
    }
  }
  return true;
}

function checkPrimeValid(arr) {
  for (let I = 0; I < arr.length; i++) {
    if (isPrimeValid(arr[i])) {
      console.log(arr[i]);
      return;
    }
  }
}

// Exemple d'utilisation
